	{'V', "version", false, "", false},
}

var shortToMeta = map[byte]*optMeta{}
var longToMeta = map[string]*optMeta{}

func init() {
	for i := range allOpts {
		m := &allOpts[i]
		shortToMeta[m.short] = m
		longToMeta[m.long] = m
	}
}

func longDisplay(m *optMeta) string {
	if m.takesValue {
		return "--" + m.long + " " + m.valueName
	}
	return "--" + m.long
}

func shortDisplay(m *optMeta) string {
	// for error messages like '--output <result.html>' (always long form in errors)
	return longDisplay(m)
}

// levenshtein distance
func lev(a, b string) int {
	la, lb := len(a), len(b)
	if la == 0 {
		return lb
	}
	if lb == 0 {
		return la
	}
	prev := make([]int, lb+1)
	cur := make([]int, lb+1)
	for j := 0; j <= lb; j++ {
		prev[j] = j
	}
	for i := 1; i <= la; i++ {
		cur[0] = i
		for j := 1; j <= lb; j++ {
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}
			cur[j] = min3(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		prev, cur = cur, prev
	}
	return prev[lb]
}

func min3(a, b, c int) int {
	if a < b {
		if a < c {
			return a
		}
		return c
	}
	if b < c {
		return b
	}
	return c
}

func findSimilarLong(input string) *optMeta {
	// input is without leading --, e.g. "no-audioo"
	bestDist := 1000000
	var best *optMeta
	for i := range allOpts {
		m := &allOpts[i]
		d := lev(input, m.long)
		if d < bestDist {
			bestDist = d
			best = m
		}
	}
	// Threshold: clap uses some confidence; we approximate:
	// if bestDist <= 3 and input length >= 3, suggest; also handle prefix cases
	// For single letter like "a", "b", etc, original suggests something, but we will also suggest closest
	// To match original for --unknown (no suggestion), need threshold: --unknown vs closest?
