func parseArgs(argv []string) (*Options, *cliError) {
	// argv includes prog name at [0]? Caller passes os.Args
	args := argv[1:]
	opts := &Options{Timeout: 60}
	seen := map[string]bool{} // long name -> seen
	providedOrder := []string{} // long names in order, deduped for Usage (except domain shows once)
	// helper to record provided
	recordProvided := func(long string) {
		// for Usage, dedupe (domain multiple shows once)
		for _, v := range providedOrder {
			if v == long {
				return
			}
		}
		providedOrder = append(providedOrder, long)
	}
	// helper to build Usage for missing TARGET / unknown with provided
	buildUsageWithProvided := func() string {
		if len(providedOrder) == 0 {
			return "Usage: executable <TARGET>"
		}
		parts := []string{"executable"}
		for _, long := range providedOrder {
			m := longToMeta[long]
			parts = append(parts, longDisplay(m))
		}
		parts = append(parts, "<TARGET>")
		return "Usage: " + strings.Join(parts, " ")
	}

	var positionals []string
	i := 0
	endOfOptions := false
	for i < len(args) {
		arg := args[i]
		if endOfOptions {
			positionals = append(positionals, arg)
			// check extra positional immediately? clap reports extra at end? For t1 t2, it reports unexpected 't2'. We should detect when len>1
			if len(positionals) > 1 {
				return nil, &cliError{msg: fmt.Sprintf("error: unexpected argument '%s' found\n\nUsage: executable [OPTIONS] <TARGET>\n\nFor more information, try '--help'.\n", positionals[1]), exitCode: 2}
			}
			i++
			continue
		}
		if arg == "--" {
			endOfOptions = true
			i++
			continue
		}
		if arg == "-" {
			// positional TARGET "-"
			positionals = append(positionals, arg)
			if len(positionals) > 1 {
				return nil, &cliError{msg: fmt.Sprintf("error: unexpected argument '%s' found\n\nUsage: executable [OPTIONS] <TARGET>\n\nFor more information, try '--help'.\n", positionals[1]), exitCode: 2}
			}
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			// long option, may contain =
			eqIdx := strings.Index(arg, "=")
			var name, val string
			var hasEq bool
			if eqIdx != -1 {
				name = arg[2:eqIdx]
				val = arg[eqIdx+1:]
				hasEq = true
			} else {
				name = arg[2:]
			}
			if name == "" {
				// arg is exactly "--"? Already handled. "--=x"? name empty, treat as unknown?
				return nil, &cliError{msg: fmt.Sprintf("error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] <TARGET>\n\nFor more information, try '--help'.\n", arg, arg, arg), exitCode: 2}
			}
			m, ok := longToMeta[name]
			if !ok {
				// unknown long, check suggestion
				similar := findSimilarLong(name)
				if similar != nil {
					usage := fmt.Sprintf("Usage: executable %s <TARGET>", longDisplay(similar))
					return nil, &cliError{msg: fmt.Sprintf("error: unexpected argument '%s' found\n\n  tip: a similar argument exists: '--%s'\n\n%s\n\nFor more information, try '--help'.\n", arg, similar.long, usage), exitCode: 2}
				}
				// generic, Usage shows provided? For unknown with prior valid options, Usage shows provided. For --unknown alone, generic [OPTIONS]. Need to handle.
				var usage string
				if len(providedOrder) == 0 {
					usage = "Usage: executable [OPTIONS] <TARGET>"
				} else {
					// show providedOrder
					parts := []string{"executable"}
					for _, long := range providedOrder {
						pm := longToMeta[long]
						parts = append(parts, longDisplay(pm))
					}
					parts = append(parts, "<TARGET>")
					usage = "Usage: " + strings.Join(parts, " ")
				}
				return nil, &cliError{msg: fmt.Sprintf("error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\n%s\n\nFor more information, try '--help'.\n", arg, arg, arg, usage), exitCode: 2}
			}
			// known long
			if m.long == "help" {
				if hasEq {
					return nil, &cliError{msg: fmt.Sprintf("error: unexpected value '%s' for '--help' found; no more were expected\n\nUsage: executable --help <TARGET>\n\nFor more information, try '--help'.\n", val), exitCode: 2}
				}
				// help wins immediately
				return nil, &cliError{msg: "__HELP__", exitCode: 0}
			}
			if m.long == "version" {
				if hasEq {
					// need to check original for --version=x? Likely similar to help. Let's assume same format.
					return nil, &cliError{msg: fmt.Sprintf("error: unexpected value '%s' for '--version' found; no more were expected\n\nUsage: executable --version <TARGET>\n\nFor more information, try '--help'.\n", val), exitCode: 2}
				}
				return nil, &cliError{msg: "__VERSION__", exitCode: 0}
			}
			if !m.takesValue {
				if hasEq {
					return nil, &cliError{msg: fmt.Sprintf("error: unexpected value '%s' for '--%s' found; no more were expected\n\nUsage: executable --%s <TARGET>\n\nFor more information, try '--help'.\n", val, m.long, m.long), exitCode: 2}
				}
				// boolean, check duplicate
				if seen[m.long] {
					return nil, &cliError{msg: fmt.Sprintf("error: the argument '--%s' cannot be used multiple times\n\nUsage: executable [OPTIONS] <TARGET>\n\nFor more information, try '--help'.\n", m.long), exitCode: 2}
				}
				seen[m.long] = true
				recordProvided(m.long)
				setBoolOpt(opts, m.long, true)
				i++
				continue
			} else {
				// takes value
				var value string
				if hasEq {
					value = val
					// check duplicate before? For -b a -b b, duplicate error. For --base-url=a --base-url=b, same. Need to check seen.
					if seen[m.long] && !m.allowMultiple {
						return nil, &cliError{msg: fmt.Sprintf("error: the argument '--%s %s' cannot be used multiple times\n\nUsage: executable [OPTIONS] <TARGET>\n\nFor more information, try '--help'.\n", m.long, m.valueName), exitCode: 2}
					}
					// validate timeout if needed
					if m.long == "timeout" {
						if err := validateTimeout(value); err != nil {
							return nil, &cliError{msg: fmt.Sprintf("error: invalid value '%s' for '--timeout <60>': %s\n\nFor more information, try '--help'.\n", value, err.Error()), exitCode: 2}
						}
						v, _ := parseTimeout(value)
						opts.Timeout = v
						opts.TimeoutSet = true
					} else {
						setValueOpt(opts, m.long, value)
					}
					if !m.allowMultiple {
						seen[m.long] = true
					}
					recordProvided(m.long)
					i++
					continue
				} else {
					// need next arg as value
					if i+1 >= len(args) {
						return nil, &cliError{msg: fmt.Sprintf("error: a value is required for '--%s %s' but none was supplied\n\nFor more information, try '--help'.\n", m.long, m.valueName), exitCode: 2}
					}
					next := args[i+1]
					// if next looks like flag (starts with - and not exactly "-"), then check if known or unknown
					if strings.HasPrefix(next, "-") && next != "-" {
						// looks like flag, determine if known
						if isKnownFlag(next) {
							return nil, &cliError{msg: fmt.Sprintf("error: a value is required for '--%s %s' but none was supplied\n\nFor more information, try '--help'.\n", m.long, m.valueName), exitCode: 2}
						} else {
							// unknown flag next, report unknown for next (not missing value)
							// need to generate unknown error for next
							return handleUnknownFlag(next, providedOrder)
						}
					}
					value = next
					if seen[m.long] && !m.allowMultiple {
						return nil, &cliError{msg: fmt.Sprintf("error: the argument '--%s %s' cannot be used multiple times\n\nUsage: executable [OPTIONS] <TARGET>\n\nFor more information, try '--help'.\n", m.long, m.valueName), exitCode: 2}
					}
					if m.long == "timeout" {
						if err := validateTimeout(value); err != nil {
							return nil, &cliError{msg: fmt.Sprintf("error: invalid value '%s' for '--timeout <60>': %s\n\nFor more information, try '--help'.\n", value, err.Error()), exitCode: 2}
						}
						v, _ := parseTimeout(value)
						opts.Timeout = v
						opts.TimeoutSet = true
					} else {
						setValueOpt(opts, m.long, value)
					}
					if !m.allowMultiple {
						seen[m.long] = true
					}
					recordProvided(m.long)
					i += 2
					continue
				}
			}
		}
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// short options, possibly combined
			// iterate chars
			j := 1
			consumedNext := false
			for j < len(arg) {
				ch := arg[j]
				m, ok := shortToMeta[ch]
				if !ok {
					// unknown short
					unknown := fmt.Sprintf("-%c", ch)
					// Usage for unknown short? Generic [OPTIONS] or with provided? Earlier -x alone gave [OPTIONS]. What about -a -x? Need to test. For now, if providedOrder empty, generic, else with provided? Let's check: -a --unknown gave Usage with --no-audio. For short unknown after valid, likely same. So use providedOrder.
					var usage string
					if len(providedOrder) == 0 {
						usage = "Usage: executable [OPTIONS] <TARGET>"
					} else {
						parts := []string{"executable"}
						for _, long := range providedOrder {
							pm := longToMeta[long]
							parts = append(parts, longDisplay(pm))
						}
						parts = append(parts, "<TARGET>")
						usage = "Usage: " + strings.Join(parts, " ")
					}
					return nil, &cliError{msg: fmt.Sprintf("error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\n%s\n\nFor more information, try '--help'.\n", unknown, unknown, unknown, usage), exitCode: 2}
				}
				if m.long == "help" {
					// -h wins immediately, ignore rest of combined? e.g., -ha? Should show help (since -h first). What about -ah? -a then -h: should show help (since -h encountered, ignore rest? But need to have recorded -a? For help, ignore. Good.
					return nil, &cliError{msg: "__HELP__", exitCode: 0}
				}
				if m.long == "version" {
					return nil, &cliError{msg: "__VERSION__", exitCode: 0}
				}
				if !m.takesValue {
					if seen[m.long] {
						return nil, &cliError{msg: fmt.Sprintf("error: the argument '--%s' cannot be used multiple times\n\nUsage: executable [OPTIONS] <TARGET>\n\nFor more information, try '--help'.\n", m.long), exitCode: 2}
					}
					seen[m.long] = true
					recordProvided(m.long)
					setBoolOpt(opts, m.long, true)
					j++
					continue
				} else {
					// takes value: if there are remaining chars in same arg, they are value (e.g., -bval, -t60)
					var value string
					if j+1 < len(arg) {
						value = arg[j+1:]
						// check duplicate
						if seen[m.long] && !m.allowMultiple {
							return nil, &cliError{msg: fmt.Sprintf("error: the argument '--%s %s' cannot be used multiple times\n\nUsage: executable [OPTIONS] <TARGET>\n\nFor more information, try '--help'.\n", m.long, m.valueName), exitCode: 2}
						}
						if m.long == "timeout" {
							if err := validateTimeout(value); err != nil {
								return nil, &cliError{msg: fmt.Sprintf("error: invalid value '%s' for '--timeout <60>': %s\n\nFor more information, try '--help'.\n", value, err.Error()), exitCode: 2}
							}
							v, _ := parseTimeout(value)
							opts.Timeout = v
							opts.TimeoutSet = true
						} else {
							setValueOpt(opts, m.long, value)
						}
						if !m.allowMultiple {
							seen[m.long] = true
						}
						recordProvided(m.long)
						// consumed whole arg
						j = len(arg)
						break
					} else {
						// need next arg
						if i+1 >= len(args) {
							return nil, &cliError{msg: fmt.Sprintf("error: a value is required for '--%s %s' but none was supplied\n\nFor more information, try '--help'.\n", m.long, m.valueName), exitCode: 2}
						}
						next := args[i+1]
						if strings.HasPrefix(next, "-") && next != "-" {
							if isKnownFlag(next) {
								return nil, &cliError{msg: fmt.Sprintf("error: a value is required for '--%s %s' but none was supplied\n\nFor more information, try '--help'.\n", m.long, m.valueName), exitCode: 2}
							} else {
								return handleUnknownFlag(next, providedOrder)
							}
						}
						value = next
						if seen[m.long] && !m.allowMultiple {
							return nil, &cliError{msg: fmt.Sprintf("error: the argument '--%s %s' cannot be used multiple times\n\nUsage: executable [OPTIONS] <TARGET>\n\nFor more information, try '--help'.\n", m.long, m.valueName), exitCode: 2}
						}
						if m.long == "timeout" {
							if err := validateTimeout(value); err != nil {
								return nil, &cliError{msg: fmt.Sprintf("error: invalid value '%s' for '--timeout <60>': %s\n\nFor more information, try '--help'.\n", value, err.Error()), exitCode: 2}
							}
							v, _ := parseTimeout(value)
							opts.Timeout = v
							opts.TimeoutSet = true
						} else {
							setValueOpt(opts, m.long, value)
						}
						if !m.allowMultiple {
							seen[m.long] = true
						}
						recordProvided(m.long)
						consumedNext = true
						j = len(arg)
						break
					}
				}
			}
			if consumedNext {
				i += 2
			} else {
				i++
			}
			continue
		}
		// positional
		positionals = append(positionals, arg)
		if len(positionals) > 1 {
			return nil, &cliError{msg: fmt.Sprintf("error: unexpected argument '%s' found\n\nUsage: executable [OPTIONS] <TARGET>\n\nFor more information, try '--help'.\n", positionals[1]), exitCode: 2}
		}
		i++
	}
	// end loop, check positionals
	if len(positionals) == 0 {
		// missing TARGET
		usage := buildUsageWithProvided()
		return nil, &cliError{msg: fmt.Sprintf("error: the following required arguments were not provided:\n  <TARGET>\n\n%s\n\nFor more information, try '--help'.\n", usage), exitCode: 2}
	}
	opts.Target = positionals[0]
	opts.TargetSet = true
	return opts, nil
}

func isKnownFlag(arg string) bool {
	if arg == "--" || arg == "-" {
		return false
	}
	if strings.HasPrefix(arg, "--") {
		eqIdx := strings.Index(arg, "=")
		var name string
		if eqIdx != -1 {
			name = arg[2:eqIdx]
		} else {
			name = arg[2:]
		}
		_, ok := longToMeta[name]
		return ok
	}
	if strings.HasPrefix(arg, "-") && len(arg) > 1 {
		// check first char after - is known short? For combined like -ab, first char known => known? Clap treats -ab as known (since -a known)? But for missing value check, next="-ab" starts with -, is it considered flag? Yes, since it looks like flag. But is it known? If first char known, then known? Let's assume if first char known, then known.
		ch := arg[1]
		_, ok := shortToMeta[ch]
		return ok
	}
	return false
}

