func validateTimeout(s string) error {
	if s == "" {
		return fmt.Errorf("cannot parse integer from empty string")
	}
	// Rust parse::<u64> allows leading +? Yes, "+60" accepted. Does it allow leading spaces? No. Does it allow "_"? No.
	// Check for invalid digits: must be digits, with optional leading +.
	start := 0
	if s[0] == '+' {
		if len(s) == 1 {
			return fmt.Errorf("invalid digit found in string")
		}
		start = 1
	}
	for i := start; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return fmt.Errorf("invalid digit found in string")
		}
	}
	// check overflow for u64
	_, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		// strconv error could be range or syntax, but we already checked syntax, so must be range
		return fmt.Errorf("number too large to fit in target type")
	}
	return nil
}

