func dump(n *html.Node, depth int) {
  indent := strings.Repeat("  ", depth)
  switch n.Type {
  case html.DocumentNode:
    fmt.Printf("%s#document\n", indent)
  case html.DoctypeNode:
    fmt.Printf("%s<!DOCTYPE %q public=%q system=%q>\n", indent, n.Data, n.Attr[0].Val, n.Attr[1].Val)
    if len(n.Attr)>0 {
