    }
  case html.ElementNode:
    fmt.Printf("%s<%s> ns=%q\n", indent, n.Data, n.Namespace)
    for _, a := range n.Attr {
      fmt.Printf("%s  @%s=%q ns=%q\n", indent, a.Key, a.Val, a.Namespace)
    }
  case html.TextNode:
    fmt.Printf("%s#text %q\n", indent, n.Data)
  case html.CommentNode:
    fmt.Printf("%s<!--%q-->\n", indent, n.Data)
  case html.ErrorNode:
    fmt.Printf("%s#err\n", indent)
  }
  for c:=n.FirstChild; c!=nil; c=c.NextSibling {
    dump(c, depth+1)
  }
}

