		} else if parentTag == "audio" && opts.NoAudio {
			shouldRemove = true
		}
		if shouldRemove {
			removeAttr(n, "src")
			return
		}
		if strings.TrimSpace(src) == "" {
			return
		}
		newURL, remove := embedMediaURL(src, base, parentURL, opts, fetcher)
		if remove {
			removeAttr(n, "src")
		} else {
			setAttr(n, "src", newURL)
		}
	}
