}

func embedMediaURL(href string, base *url.URL, parentURL *url.URL, opts *Options, fetcher *Fetcher) (string, bool) {
	hrefTrimmed := strings.TrimSpace(href)
	if isDataURL(hrefTrimmed) {
		return normalizeDataURL(hrefTrimmed), false
	}
	if isFragmentOnly(hrefTrimmed) {
		return hrefTrimmed, false
	}
	abs := resolveURL(base, hrefTrimmed)
	if abs == nil {
		return "data:text/plain;base64,", false
	}
	frag := ""
	if abs.Fragment != "" {
		frag = "#" + abs.Fragment
	}
	fetchURL := *abs
	fetchURL.Fragment = ""
	res := fetcher.fetch(&fetchURL, parentURL)
	if res.blocked {
		return abs.String(), false
	}
	if res.errType == "file-not-found" {
		return "", true
	}
	if res.errType == "network" || res.errType == "status" {
		return abs.String(), false
	}
	dataURL := encodeDataURL(res.mediatype, res.params, res.data)
	if frag != "" {
		dataURL += frag
	}
	return dataURL, false
}

