				return embedCSSURL(urlStr, base, parentURL, opts, fetcher)
			})
			processedBlocks = append(processedBlocks, processed)
		}
		// Process rest (non-font-face parts) with placeholder? But restlices are parts between blocks. Need to process each rest part with placeholder for urls.
