		// Let's do: replace each block with marker like "__FONTFACE_0__", process whole CSS (with markers) using placeholder for urls (markers have no urls, so safe), then replace markers with processedBlocks.
		markerCSS := cssStr
		for i, b := range blocks {
			marker := fmt.Sprintf("__FONTFACE_%d__", i)
			// Replace first occurrence of b with marker? Since blocks may repeat? Use Replace with count 1? But b may appear multiple times? For simplicity, replace all? Better to use restlices to reconstruct.
			_ = marker
			_ = b
		}
		// Instead, use restlices: restlices are the parts outside blocks, in order: rest[0] + block[0] + rest[1] + block[1] + ... + rest[n]
		// Process each rest part with placeholder
		var out strings.Builder
		for i, rest := range restlices {
			processedRest := processCSSUrls(rest, func(urlStr string) (string, bool) {
				return placeholderPNG, false
			})
			out.WriteString(processedRest)
			if i < len(processedBlocks) {
				out.WriteString(processedBlocks[i])
			}
		}
		return out.String()
	} else {
		// Normal (not -i): embed all urls
		return processCSSUrls(cssStr, func(urlStr string) (string, bool) {
			return embedCSSURL(urlStr, base, parentURL, opts, fetcher)
		})
	}
}

func embedCSSURL(urlStr string, base *url.URL, parentURL *url.URL, opts *Options, fetcher *Fetcher) (string, bool) {
	trimmed := strings.TrimSpace(urlStr)
	if isDataURL(trimmed) {
		return normalizeDataURL(trimmed), false
	}
	// fragment-only and empty already handled by caller (processCSSUrls doesn't call for those). Good. But just in case:
	if trimmed == "" {
		return "", true
	}
	if strings.HasPrefix(trimmed, "#") {
		return trimmed, false // should not happen (caller handles), but return as is
	}
	abs := resolveURL(base, trimmed)
	if abs == nil {
		return "data:text/plain;base64,", false
	}
	frag := ""
	if abs.Fragment != "" {
		frag = "#" + abs.Fragment
	}
	fetchURL := *abs
	fetchURL.Fragment = ""
	res := fetcher.fetch(&fetchURL, parentURL)
	if res.blocked {
		return abs.String(), false
	}
	if res.errType == "file-not-found" {
		return "", true
	}
	if res.errType == "network" || res.errType == "status" {
		return abs.String(), false
	}
	dataURL := encodeDataURL(res.mediatype, res.params, res.data)
	if frag != "" {
		dataURL += frag
	}
	return dataURL, false
}

// extractFontFaceBlocks splits CSS into font-face blocks and rest parts
// Returns (blocks, rests) where rests has len(blocks)+1, and original = rests[0]+blocks[0]+rests[1]+...+blocks[n-1]+rests[n]
func extractFontFaceBlocks(css string) ([]string, []string) {
	var blocks []string
	var rests []string
	i := 0
	n := len(css)
	lastRestStart := 0
	for i < n {
		// skip comments (preserve as part of rest, but need to avoid matching @font-face inside comments)
		if i+1 < n && css[i] == '/' && css[i+1] == '*' {
			end := strings.Index(css[i+2:], "*/")
			if end == -1 {
				break
			}
			i += 2 + end + 2
			continue
		}
		// check for @font-face
		if isFontFaceToken(css, i) {
			// find '{'
			j := i + 10
			for j < n && isCSSSpace(css[j]) {
				j++
			}
			if j >= n || css[j] != '{' {
				i++
				continue
			}
			// find matching '}'
			k := j + 1
			depth := 1
			for k < n && depth > 0 {
				if k+1 < n && css[k] == '/' && css[k+1] == '*' {
					end := strings.Index(css[k+2:], "*/")
					if end == -1 {
						k = n
						break
					}
					k += 2 + end + 2
					continue
				}
				if css[k] == '"' || css[k] == '\'' {
					quote := css[k]
					k++
					for k < n {
						if css[k] == '\\' && k+1 < n {
							k += 2
							continue
						}
						if css[k] == quote {
							k++
							break
						}
						k++
					}
					continue
				}
				if css[k] == '{' {
					depth++
				} else if css[k] == '}' {
					depth--
				}
				k++
			}
			// block is css[i:k]
			rests = append(rests, css[lastRestStart:i])
			blocks = append(blocks, css[i:k])
			lastRestStart = k
			i = k
			continue
		}
		// skip strings
		if css[i] == '"' || css[i] == '\'' {
			quote := css[i]
			i++
			for i < n {
				if css[i] == '\\' && i+1 < n {
					i += 2
					continue
				}
				if css[i] == quote {
					i++
					break
				}
				i++
			}
			continue
		}
		i++
	}
	rests = append(rests, css[lastRestStart:])
	return blocks, rests
}

