				newURL = abs.String()
			} else {
				dataURL := encodeDataURL(res.mediatype, res.params, res.data)
				if frag != "" {
					dataURL += frag
				}
				newURL = dataURL
			}
		}
	}
	if shouldRemove {
		// remove both href attributes? Original file missing svg image gave <image> (no href, removed). If both present and first missing, remove both? Assume yes.
		var newAttrs []html.Attribute
		for _, a := range n.Attr {
			if !(a.Key == "href" && (a.Namespace == "" || a.Namespace == "xlink")) {
				newAttrs = append(newAttrs, a)
			}
		}
		n.Attr = newAttrs
	} else {
		// set both to newURL (preserving order and namespaces)
		for _, f := range found {
			n.Attr[f.idx].Val = newURL
		}
	}
