			found = append(found, attrPos{idx: i, ns: a.Namespace, val: a.Val})
		}
	}
	if len(found) == 0 {
		return
	}
	// First wins: embed first URL, set both to same
	firstVal := strings.TrimSpace(found[0].val)
	if firstVal == "" {
		return
	}
