func handleFilePathTarget(path string, opts *Options, fetcher *Fetcher) int {
	// Convert path to file:// URL for fetching/logging
	absPath, err := filepathAbs(path)
	if err != nil {
		absPath = path
	}
	// Ensure absolute? For relative paths like "hello.html" in /tmp/.../dir, absPath should be /tmp/.../hello.html. Good.
	fileURLStr := "file://" + absPath
	// Note: absPath starts with /, so file:// + /tmp/... = file:///tmp/... (three slashes). Good.
	u, err := url.Parse(fileURLStr)
	if err != nil {
		if !opts.Quiet {
			fmt.Fprintln(os.Stderr, "Error: could not retrieve target document")
		}
		return 1
	}
	return handleFileURL(u, path, opts, fetcher, false)
}

func handleFileURLTarget(target string, opts *Options, fetcher *Fetcher) int {
