        elif self.path=="/img.png":
            self.send_response(200); self.send_header("Content-Type","image/png"); self.end_headers(); self.wfile.write(b"\x89PNGDATA")
        elif self.path=="/favicon.ico":
            self.send_response(200); self.send_header("Content-Type","image/x-icon"); self.end_headers(); self.wfile.write(b"FAVICON")
        else:
            self.send_response(404); self.end_headers(); self.wfile.write(b"nf")
