package main

import (
	"bytes"
	"strings"

	"golang.org/x/text/encoding/htmlindex"
)

// detectInputCharset detects charset for HTML input
// data: raw bytes
// contentTypeParams: e.g., ";charset=utf-8" from HTTP Content-Type (or "" for file/stdin)
// isHTTP: true for http targets (default windows-1252), false for file/stdin/data (default utf-8)
// Returns charset label to use for decoding (e.g., "utf-8", "windows-1252", "iso-8859-1", etc), and data without BOM (if BOM present, stripped)
func detectInputCharset(data []byte, contentTypeParams string, isHTTP bool) (string, []byte) {
	// Check BOM
	if len(data) >= 3 && data[0] == 0xEF && data[1] == 0xBB && data[2] == 0xBF {
		return "utf-8", data[3:]
	}
	if len(data) >= 2 && data[0] == 0xFF && data[1] == 0xFE {
		return "utf-16le", data[2:]
	}
	if len(data) >= 2 && data[0] == 0xFE && data[1] == 0xFF {
		return "utf-16be", data[2:]
	}
	// Check Content-Type params (for http)
	if contentTypeParams != "" {
		parts := strings.Split(contentTypeParams, ";")
		for _, p := range parts {
			p = strings.TrimSpace(p)
			if strings.HasPrefix(strings.ToLower(p), "charset=") {
				cs := strings.TrimSpace(p[8:])
				cs = strings.Trim(cs, "\"'")
				if cs != "" && validateEncoding(cs) {
					return cs, data
				}
			}
		}
	}
	// Check meta charset in first 4096 bytes (as ASCII, case-insensitive)
	limit := len(data)
	if limit > 4096 {
		limit = 4096
	}
	head := data[:limit]
	// Search for charset= pattern
	// Use case-insensitive search for "charset"
	lowerHead := bytes.ToLower(head)
	idx := bytes.Index(lowerHead, []byte("charset"))
	if idx != -1 {
		// Find = after charset (skipping spaces)
		j := idx + 7
		for j < len(head) && (head[j] == ' ' || head[j] == '\t' || head[j] == '\n' || head[j] == '\r' || head[j] == '\f') {
			j++
		}
		if j < len(head) && head[j] == '=' {
			j++
			for j < len(head) && (head[j] == ' ' || head[j] == '\t' || head[j] == '\n' || head[j] == '\r' || head[j] == '\f') {
				j++
			}
			if j < len(head) {
				var csBytes []byte
				if head[j] == '"' || head[j] == '\'' {
					quote := head[j]
					j++
					start := j
					for j < len(head) && head[j] != quote {
						j++
					}
					csBytes = head[start:j]
				} else {
					start := j
					for j < len(head) && head[j] != ' ' && head[j] != '\t' && head[j] != '\n' && head[j] != '\r' && head[j] != '\f' && head[j] != ';' && head[j] != '"' && head[j] != '\'' && head[j] != '>' && head[j] != '/' {
						j++
					}
					csBytes = head[start:j]
				}
				cs := string(csBytes)
				cs = strings.TrimSpace(cs)
				if cs != "" && validateEncoding(cs) {
					return cs, data
				}
			}
		}
	}
	// Default
	if isHTTP {
		return "windows-1252", data
	}
	return "utf-8", data
}

// decodeHTML decodes HTML bytes to UTF-8 string using detected charset, returns (decoded string, detected charset label)
func decodeHTML(data []byte, contentTypeParams string, isHTTP bool) (string, string) {
	charset, stripped := detectInputCharset(data, contentTypeParams, isHTTP)
	// Use htmlindex to decode (which handles windows-1252 mapping, etc.)
	// For utf-8, use lossy (ToValidUTF8) for invalid? htmlindex utf-8 decoder also handles? Use decodeWithCharset which uses htmlindex (which for utf-8 should be lossy? Actually htmlindex utf-8 decoder may return error on invalid? Our decodeWithCharset handles error by returning ToValidUTF8. Good.)
	decoded := decodeWithCharset(stripped, charset)
	return decoded, charset
}
