	// Use case-insensitive search for "charset"
	lowerHead := bytes.ToLower(head)
	idx := bytes.Index(lowerHead, []byte("charset"))
	if idx != -1 {
		// Find = after charset (skipping spaces)
		j := idx + 7
		for j < len(head) && (head[j] == ' ' || head[j] == '\t' || head[j] == '\n' || head[j] == '\r' || head[j] == '\f') {
			j++
		}
		if j < len(head) && head[j] == '=' {
			j++
			for j < len(head) && (head[j] == ' ' || head[j] == '\t' || head[j] == '\n' || head[j] == '\r' || head[j] == '\f') {
				j++
			}
			if j < len(head) {
				var csBytes []byte
				if head[j] == '"' || head[j] == '\'' {
					quote := head[j]
					j++
					start := j
					for j < len(head) && head[j] != quote {
						j++
					}
					csBytes = head[start:j]
				} else {
					start := j
					for j < len(head) && head[j] != ' ' && head[j] != '\t' && head[j] != '\n' && head[j] != '\r' && head[j] != '\f' && head[j] != ';' && head[j] != '"' && head[j] != '\'' && head[j] != '>' && head[j] != '/' {
						j++
					}
					csBytes = head[start:j]
				}
				cs := string(csBytes)
				cs = strings.TrimSpace(cs)
				if cs != "" && validateEncoding(cs) {
					return cs, data
				}
			}
