}

// decodeHTML decodes HTML bytes to UTF-8 string using detected charset, returns (decoded string, detected charset label)
func decodeHTML(data []byte, contentTypeParams string, isHTTP bool) (string, string) {
	charset, stripped := detectInputCharset(data, contentTypeParams, isHTTP)
	// Use htmlindex to decode (which handles windows-1252 mapping, etc.)
